namespace RuBackend.Harness.Policy;

/// <summary>
/// Canonical representation used by reusable external-directory approvals. The
/// wildcard is generated by the host, never accepted from the approval request, so a
/// model cannot broaden a directory grant by smuggling glob syntax into a path.
/// </summary>
internal static class ExternalDirectoryPolicy
{
    private const string DescendantSuffix = "/**";
    private const int MaxPolicyPathLength = 4096;

    public static bool TryCreatePattern(string canonicalDirectory, out string pattern)
    {
        pattern = string.Empty;
        if (string.IsNullOrWhiteSpace(canonicalDirectory)
            || canonicalDirectory.Contains('\0')
            || canonicalDirectory.Contains('*')
            || canonicalDirectory.Contains('?'))
        {
            return false;
        }

        string normalized;
        try
        {
            normalized = Path.TrimEndingDirectorySeparator(Path.GetFullPath(canonicalDirectory));
        }
        catch (ArgumentException)
        {
            return false;
        }

        var root = Path.GetPathRoot(normalized);
        if (string.IsNullOrWhiteSpace(normalized)
            || string.IsNullOrWhiteSpace(root)
            || string.Equals(
                normalized,
                Path.TrimEndingDirectorySeparator(Path.GetFullPath(root)),
                StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var normalizedForPattern = normalized.Replace('\\', '/').TrimEnd('/');
        if (normalizedForPattern.Length > MaxPolicyPathLength - DescendantSuffix.Length)
        {
            return false;
        }

        pattern = normalizedForPattern + DescendantSuffix;
        return true;
    }
}
